source('mp10_hypothesis_followup_v1/scripts/common.R')
reg<-rd('model_registry.tsv');sc<-rd('sample_level_scores.tsv.gz');pr<-rd('coverage.tsv.gz');q<-old('specimen_exposure_eligibility.tsv');cy<-rd('treg_cycle_composition.tsv');clinical<-rd('clinical_covariate.tsv')[,.(sample_uid,clinical_type)];cells<-old('analysis_cell_metadata.tsv.gz');epi<-cells[analysis_major_c2l_final=='Epithelial'];ec<-fread(file.path(P,'mp10_subtype_screen_round1/tables/epithelial_existing_metadata.tsv.gz'),select=c('cell_id','epi_allgene_cluster','annotation'));setnames(ec,'cell_id','barcode');epi<-merge(epi,ec,by='barcode',all.x=TRUE);cl<-epi[!is.na(epi_allgene_cluster),.N,by=epi_allgene_cluster][order(-N)];dominant<-cl$epi_allgene_cluster[1];stopifnot(cl$N[1]/nrow(epi)>=.05);mix<-epi[,.(epi_major_fraction=mean(!is.na(epi_allgene_cluster)&epi_allgene_cluster==dominant),missing_subtype_fraction=mean(is.na(epi_allgene_cluster))),by=sample_uid];put(mix,'Epi_original_cluster_covariates.tsv');put(data.table(metric='epi_major_fraction',definition=paste('fraction in globally most abundant original cluster',dominant),selection='cell counts only; before association; missing labels retained in denominator'),'composition_covariate_definition.tsv')
# registry has no clinical model because reliability is not established; audit separately.
results<-list();members<-list();influences<-list();excluded<-list();settings<-unique(reg$setting)
metric_for<-function(n,setting){if(setting=='Full')n<-sub('_M20$','_Full',n);if(grepl('^SREBF[12]_M20$',n)){n<-paste0(n,switch(setting,DoRothEA_AB='_DoR',TF_unique='_unique',remove_NECTIN2='_noNECTIN2',''))};n}
for(i in seq_len(nrow(reg))){r<-reg[i];xx<-metric_for(r$x,r$setting);yy<-metric_for(r$y,r$setting);d<-copy(q[,.(sample_uid,dataset,patient_uid_recorded,main_patient,replacement_patient,Q50,Q95,Q50_z,Q95_z)]);epr<-pr[profile_type=='Epi_all',.(sample_uid,epi_n=n_cells,epi_RNA=median_log_nCount)];d<-merge(d,epr,by='sample_uid',all.x=TRUE);d<-merge(d,mix,by='sample_uid',all.x=TRUE);d<-merge(d,clinical,by='sample_uid',all.x=TRUE)
 if(xx=='MP10_Q50')d[,x:=Q50_z]else if(xx=='MP10_Q95')d[,x:=Q95_z]else{ex<-sc[profile_type=='Epi_all'&metric==xx,.(sample_uid,x=score)];d<-merge(d,ex,by='sample_uid',all.x=TRUE)}
 ct<-r$celltype;rp<-pr[profile_type==ct,.(sample_uid,n_cells,receiver_RNA=median_log_nCount,receiver_MT=median_mt)];d<-merge(d,rp,by='sample_uid',all.x=TRUE);if(r$cohort=='NC_matched' && r$covariate%in%c('receiver_RNA','receiver_MT')){nq<-pr[profile_type=='Treg_NC',.(sample_uid,NC_RNA=median_log_nCount,NC_MT=median_mt)];d<-merge(d,nq,by='sample_uid',all.x=TRUE);d[,receiver_RNA:=NC_RNA];d[,receiver_MT:=NC_MT]};d<-merge(d,cy[,.(sample_uid,n_cycling,n_noncycling,n_invalid,cycling_adjust=cycling_fraction)],by='sample_uid',all.x=TRUE)
 if(r$method=='quasibinomial')d[,y:=cycling_adjust]else{ys<-sc[profile_type==ct & metric==yy,.(sample_uid,y=score)];d<-merge(d,ys,by='sample_uid',all.x=TRUE)}
 d[,patient_ok:=if(r$patient=='main')main_patient else replacement_patient];d[,coverage_ok:=!is.na(n_cells)&n_cells>=r$min_cells & epi_n>=r$min_cells];if(r$cohort=='NC_matched'){nc<-pr[profile_type=='Treg_NC'&n_cells>=r$min_cells,sample_uid];d[,coverage_ok:=coverage_ok&sample_uid%in%nc]}
 d[,dataset_ok:=r$omit_dataset=='none'|dataset!=r$omit_dataset];d[,values_ok:=is.finite(x)&is.finite(y)];if(r$method=='quasibinomial')d[,values_ok:=values_ok & n_invalid==0];if(r$covariate!='none')d[,values_ok:=values_ok & is.finite(get(r$covariate))]
 d[,included:=patient_ok&coverage_ok&dataset_ok&values_ok];d[,exclusion_reason:=fifelse(!patient_ok,'patient_representative',fifelse(!dataset_ok,'LODO',fifelse(!coverage_ok,'profile_below_min_cells_or_absent',fifelse(!values_ok,'missing_score_or_invalid_classification','included'))))];excluded[[i]]<-d[,.(model_id=r$model_id,sample_uid,celltype=ct,n_cells,x,y,cycling_adjust,receiver_RNA,receiver_MT,epi_RNA,exclusion_reason,included)]
 dd<-d[included==TRUE];setorder(dd,sample_uid);n<-nrow(dd);nu<-uniqueN(dd$patient_uid_recorded);nd<-uniqueN(dd$dataset);reason<-'';status<-'completed';beta<-se<-lo<-hi<-p<-disp<-df<-rank<-maxhat<-NA_real_
 if(nu<4)reason<-'fewer_than_4_recorded_patient_units';if(!any(is.finite(d$x)))reason<-'predictor_score_not_evaluable';if(!any(is.finite(d$y)))reason<-'endpoint_score_not_evaluable';if(n!=nu)stop('Repeated recorded patient units in model ',r$model_id)
 if(!nzchar(reason)){
  terms<-c(if(nd>1)'dataset',if(r$covariate!='none')r$covariate,'x');form<-reformulate(terms,response=if(r$method=='quasibinomial')'cbind(n_cycling,n_noncycling)'else'y');X<-model.matrix(reformulate(terms),dd);rank<-qr(X)$rank;df<-n-rank
  if(rank<ncol(X))reason<-'rank_deficient'else if(df<3)reason<-'residual_df_below_3'else if(sd(dd$x)<1e-10)reason<-'no_predictor_variation'else if(sd(dd$y)<1e-10)reason<-'no_endpoint_variation'
  if(!nzchar(reason))tryCatch({
   if(r$method=='HC3'){
    fit<-lm(form,dd);h<-hatvalues(fit);if(any(h>=1-1e-10))stop('unit_leverage_HC3_undefined');V0<-solve(crossprod(X));V<-V0%*%crossprod(X,X*as.numeric(residuals(fit)^2/(1-h)^2))%*%V0;beta<-coef(fit)['x'];se<-sqrt(V['x','x']);maxhat<-max(h);influences[[i]]<-data.table(model_id=r$model_id,sample_uid=dd$sample_uid,leverage=h,cooks_distance=cooks.distance(fit),standardized_residual=rstandard(fit),x=dd$x,y=dd$y)
   }else{
    fit<-glm(form,dd,family=quasibinomial());ss<-summary(fit);beta<-coef(fit)['x'];se<-ss$coefficients['x','Std. Error'];disp<-ss$dispersion;h<-hatvalues(fit);maxhat<-max(h);if(!fit$converged||!is.finite(disp)||disp<=0||se>10||any(!is.finite(coef(fit))))stop('quasibinomial_degenerate_or_separated');influences[[i]]<-data.table(model_id=r$model_id,sample_uid=dd$sample_uid,leverage=h,cooks_distance=cooks.distance(fit),standardized_residual=rstandard(fit),x=dd$x,y=dd$y)
   }
   if(!is.finite(se)||se<=0)stop('invalid_SE');p<-2*pt(-abs(beta/se),df);lo<-beta-qt(.975,df)*se;hi<-beta+qt(.975,df)*se
  },error=function(e){reason<<-conditionMessage(e)})
 }
 if(nzchar(reason)){status<-'not_evaluable';beta<-se<-lo<-hi<-p<-NA_real_}
 members[[i]]<-dd[,.(model_id=r$model_id,sample_uid,patient_uid_recorded,dataset,celltype=ct,n_cells,x,y,epi_RNA,receiver_RNA,receiver_MT,cycling_fraction=cycling_adjust)]
 results[[i]]<-cbind(r,data.table(metric_x=xx,metric_y=yy,status=status,reason=reason,beta=beta,se=se,CI_low=lo,CI_high=hi,P=p,n_profile_eligible=sum(d$patient_ok&d$coverage_ok&d$dataset_ok),n_specimens=n,n_recorded_patient_units=nu,n_datasets=nd,dataset_counts=paste(dd[,.N,by=dataset][order(dataset),paste0(dataset,':',N)],collapse=';'),residual_df=df,design_rank=rank,dispersion=disp,max_leverage=maxhat,input_hash=digest(list(dd,xx,yy,r),algo='sha256'),OR=if(r$method=='quasibinomial')exp(beta)else NA_real_,OR_low=if(r$method=='quasibinomial')exp(lo)else NA_real_,OR_high=if(r$method=='quasibinomial')exp(hi)else NA_real_))
 if(i%%100==0)cat('MODELS',i,nrow(reg),'\n')
}
z<-rbindlist(results,fill=TRUE);z[,q:=p.adjust(P,'BH',n=unique(planned_n)),by=FDR_family];z[,testable_n:=sum(is.finite(P)),by=FDR_family];put(z,'model_results.tsv.gz');put(rbindlist(members,fill=TRUE),'model_membership.tsv.gz');put(rbindlist(excluded,fill=TRUE),'model_eligibility.tsv.gz');put(rbindlist(influences,fill=TRUE),'model_influence.tsv.gz');put(z[,.(planned_n=unique(planned_n),registered_n=.N,testable_n=sum(is.finite(P)),n_NE=sum(status!='completed')),by=FDR_family],'FDR_family_audit.tsv');thread_audit('models_complete');cat('MODELS COMPLETE\n')
